mapper.select:
SELECT r.id, r.total_amount, r.operator, r.opttime, r.createtime, u.name operator_name, (SELECT COUNT(*) FROM t_erp_purchase_form_payment pay WHERE pay.period_rollover_id = r.id) relation_count FROM t_erp_fin_account_period_rollover r LEFT JOIN t_userinfo u ON u.id = r.operator WHERE r.acct = #{params.acct}
AND r.opttime >= #{params.fromDate}
AND r.opttime <= #{params.toDate}
ORDER BY r.id ASC
